    /// <summary>
    /// Category group, Use Item Attributes, Product Pricing Attribute fields must be visible only for Rebate Item Groups
    /// </summary>
    /// <param name="sender">Get Table buffer</param>
    /// <param name="e"> Get form data source args</param>
    [
        FormDataSourceEventHandler(formDataSourceStr(TAMRebateGroup, TAMRebateGroup), FormDataSourceEventType::Activated),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")
    ]
    public static void TAMRebateGroup_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
    {
        TAMRebateGroup rebateGroup = sender.cursor();
        
        boolean isVisible;

        if(rebateGroup.ModuleInventCustVend == ModuleInventCustVend::Invent)
        {
            isVisible = true;
        }

        sender.object(fieldNum(TAMRebateGroup, METCategoryGroup)).visible(isVisible);
    }

