/// <summary>
/// update design on the record selection change
/// </summary>
/// <param name="sender">TAMRebateGroup data source</param>
/// <param name="e">event</param>
[FormDataSourceEventHandler(formDataSourceStr(TAMRebateGroup, TAMRebateGroup), FormDataSourceEventType::SelectionChanged),
    SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
public static void TAMRebateGroup_OnSelectionChanged(FormDataSource sender, FormDataSourceEventArgs e)
{
    METTAMRebateGroupFormEventHandler::METUpdateDesign(sender.formRun());
}

    /// <summary>
    /// Enable/disable control elements based on different conditions
    /// </summary>
    /// <param name = "_formRun"><c>FormRun</c> object</param>
    public static void METUpdateDesign(FormRun _formRun)
    {
        TAMRebateGroup rebateGroup = _formRun.dataSource(tableStr(TAMRebateGroup)).cursor();
        boolean isEnabled = true;
            
        if(rebateGroup.ModuleInventCustVend == ModuleInventCustVend::Invent)
        {
            isEnabled = false;
        }

        _formRun.design().controlName(formControlStr(TAMRebateGroup,TAMRebateGroupLink )).enabled(isEnabled);
        _formRun.design().controlName(formControlStr(TAMRebateGroup,TAMRebateGroupAddItemsController )).enabled(isEnabled);
    }
